import { createBrowserRouter } from "react-router-dom";
import AboutUsPage from "./pages/AboutUsPage";
import ContactUsPage from "./pages/ContactUsPage";
import HowToUsePage from "./pages/HowToUsePage";
import PrivacyPolicyPage from "./pages/PrivacyPolicyPage";
import TermsOfServicePage from "./pages/TermOfServicePage";
import NotFoundPage from "./pages/NotFoundPage";
import App from "./App";
import FbDownloader from "./pages/FbDownloader";
import TiktokDownloader from "./pages/TiktokDownloader";
import TwetterDownloader from "./pages/TwetterDownloader";
import IGDownloader from "./pages/IGDownloader";
import YTDownloader from "./pages/YTDownloader";

const routes = createBrowserRouter([
    { path:'/', element:<App/> },
    { path:'/twetter-downloader', element:<TwetterDownloader/> },
    { path:'/instagram-downloader', element:<IGDownloader/> },
    { path:'/youtube-downloader', element:<YTDownloader/> },
    { path:'/tiktok-downloader', element:<TiktokDownloader/> },
    { path:'/facebook-downloader', element:<FbDownloader/> },
    { path:'/how-to-use', element:<HowToUsePage/> },
    { path:'/about', element:<AboutUsPage/> },
    { path:'/contact', element:<ContactUsPage/> },
    { path:'/privacy', element:<PrivacyPolicyPage/> },
    { path:'/terms', element:<TermsOfServicePage/> },
    { path:'/*', element:<NotFoundPage/> },
])

export default routes;
